CustomCss:
[data-theme="dark"] body,body{background:var(--bg)}
[data-theme="dark"] header,[data-theme="dark"] nav{background:#050709}
[data-theme="dark"] .sc,[data-theme="dark"] .form,[data-theme="dark"] table{border-color:#1C232C}
[data-theme="dark"] .ni.active{background:rgba(76,154,255,.16)}
[data-theme="dark"] .code{color:#4C9AFF;text-shadow:0 0 10px rgba(76,154,255,.5)}
[data-theme="dark"] .dot{box-shadow:0 0 8px var(--g)}
h2{padding-bottom:8px;border-bottom:1px solid var(--b)}
.form,.sc,.ig,table{border-radius:8px}
.ni{border-left-width:3px}
button.bp,button.bd,button.bw,button.bsm{border-radius:6px;font-weight:600}
input,select,textarea{border-radius:6px}
input:focus,select:focus,textarea:focus{box-shadow:0 0 0 3px rgba(76,154,255,.22)}
